+        <div class="product-meta">
+          <span>${product.price}</span>
+          <span class="rating" aria-label="Rated ${product.rating} out of 5">${product.rating}/5</span>
+        </div>
+      </div>
+    </article>
+  `).join("");
+}
+
+function setMenuState(isOpen) {
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+  navToggle.querySelector(".sr-only").textContent = isOpen ? "Close navigation menu" : "Open navigation menu";
+  primaryMenu.classList.toggle("is-open", isOpen);
+}
+
+function validateEmail() {
+  const email = emailInput.value.trim();
+
+  if (!email) {
+    emailInput.setAttribute("aria-invalid", "true");
+    emailError.textContent = "Enter your email address to sign up.";
+    return false;
+  }
+
+  if (!emailInput.validity.valid) {
