+const products = [
+  {
+    name: "Cloudknit Lounge Set",
+    description: "Breathable knit separates made for travel days, slow Sundays, and everything between.",
+    price: "$128",
+    rating: "4.9",
+    badge: "Bestseller",
+    colors: ["#e9d8c7", "#b98767"]
+  },
+  {
+    name: "Stoneware Dinner Kit",
+    description: "A twelve-piece table setting with hand-finished edges and dishwasher-safe durability.",
+    price: "$96",
+    rating: "4.8",
+    badge: "New",
+    colors: ["#dce4dc", "#6b816f"]
+  },
+  {
+    name: "Daily Reset Body Oil",
+    description: "Fast-absorbing botanical oils with a warm cedar and citrus finish.",
+    price: "$34",
+    rating: "4.7",
+    badge: "Clean pick",
+    colors: ["#f1dac0", "#9b4f2f"]
+  }
+];
+
+const productGrid = document.querySelector("#product-grid");
+const navToggle = document.querySelector(".nav-toggle");
+const primaryMenu = document.querySelector("#primary-menu");
+const newsletterForm = document.querySelector("#newsletter-form");
+const emailInput = document.querySelector("#email");
+const emailError = document.querySelector("#email-error");
+const formSuccess = document.querySelector("#form-success");
+
+function renderProducts() {
+  productGrid.innerHTML = products.map((product) => `
+    <article class="product-card">
+      <div class="product-art" style="--swatch-one: ${product.colors[0]}; --swatch-two: ${product.colors[1]};" aria-hidden="true">
+        <span class="product-badge">${product.badge}</span>
+      </div>
+      <div class="product-info">
+        <h3>${product.name}</h3>
+        <p>${product.description}</p>
+        <div class="product-meta">
+          <span>${product.price}</span>
+          <span class="rating" aria-label="Rated ${product.rating} out of 5">${product.rating}/5</span>
+        </div>
+      </div>
+    </article>
+  `).join("");
+}
+
+function setMenuState(isOpen) {
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+  navToggle.querySelector(".sr-only").textContent = isOpen ? "Close navigation menu" : "Open navigation menu";
+  primaryMenu.classList.toggle("is-open", isOpen);
+}
+
+function validateEmail() {
+  const email = emailInput.value.trim();
+
+  if (!email) {
+    emailInput.setAttribute("aria-invalid", "true");
+    emailError.textContent = "Enter your email address to sign up.";
+    return false;
+  }
+
+  if (!emailInput.validity.valid) {
+    emailInput.setAttribute("aria-invalid", "true");
+    emailError.textContent = "Enter an email address in the format name@example.com.";
+    return false;
+  }
+
+  emailInput.removeAttribute("aria-invalid");
+  emailError.textContent = "";
+  return true;
+}
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+  setMenuState(!isOpen);
+});
+
+primaryMenu.addEventListener("click", (event) => {
+  if (event.target instanceof HTMLAnchorElement) {
+    setMenuState(false);
+  }
+});
+
+document.addEventListener("keydown", (event) => {
+  if (event.key === "Escape" && navToggle.getAttribute("aria-expanded") === "true") {
+    setMenuState(false);
+    navToggle.focus();
+  }
+});
+
+emailInput.addEventListener("input", () => {
+  if (emailInput.getAttribute("aria-invalid") === "true") {
+    validateEmail();
+  }
+  formSuccess.textContent = "";
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  formSuccess.textContent = "";
+
+  if (!validateEmail()) {
+    emailInput.focus();
+    return;
+  }
+
+  formSuccess.textContent = "Thanks for joining. Watch your inbox for the next Northline edit.";
+  newsletterForm.reset();
+});
+
+renderProducts();
+

')
